INSERT INTO rooms (number, floor, kind, nightly_rate)
VALUES ('104', 1, 'standard', 118.0);
SELECT COUNT(*) AS n FROM v_room_rates;

CREATE VIEW v_suites AS
SELECT number, nightly_rate FROM rooms
WHERE kind = 'suite';
SELECT COUNT(*) AS n FROM v_suites;

CREATE VIEW v_deluxe AS
SELECT number, nightly_rate FROM rooms
WHERE kind = 'deluxe';
SELECT COUNT(*) AS n FROM v_deluxe
WHERE nightly_rate > 176;

CREATE VIEW v_a AS SELECT 1 AS x;
CREATE VIEW v_b AS SELECT 2 AS y;
SELECT name FROM sqlite_master
WHERE type = 'view';

CREATE VIEW v_base AS
SELECT number, nightly_rate FROM rooms
WHERE nightly_rate < 200;
CREATE VIEW v_cheap AS
SELECT number FROM v_base WHERE nightly_rate < 130;
SELECT COUNT(*) AS n FROM v_cheap;
